void SpawnObject(GameObject prefab, Vector3? position = null, Quaternion? rotation = null)
{
    Vector3 pos = position ?? Vector3.zero;
    Quaternion rot = rotation ?? Quaternion.identity;
    Instantiate(prefab, pos, rot);
}

// Call:
SpawnObject(enemyPrefab); // at origin
SpawnObject(enemyPrefab, new Vector3(0, 0, 5)); // at specific position
